class Solution {
public:
    string convertToTitle(int columnNumber) {
        int temp = columnNumber;
        string ans = "";

        while(temp != 0){
            // Shift down by 1 to make it 0-indexed (0 to 25)
            temp--; 

            int modCatch = temp % 26;
            ans.push_back(65 + modCatch);

            temp = temp / 26;
        }

        // Reverse the string at the end since we calculated from right to left
        reverse(ans.begin(), ans.end());

        return ans;
    }
};

